import datetime,fcntl,hashlib,json,shutil,subprocess
from pathlib import Path
import psutil
H=Path(__file__).resolve().parent;ROOT=H.parents[1]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,x):p.write_text(json.dumps(x,indent=2)+'\n')
def main():
 plan=H/'gpu-coverage-frozen-plan-nov3.json';m=json.loads(plan.read_text());state=json.loads((H/'live-nov3-gpu-coverage-custody.json').read_text());a=json.loads((H/'live-nov3-gpu-coverage-independent-analysis.json').read_text());rows=list(a['rows'].values())
 assert sha(plan)==state['manifest_sha256'];bad=[p for p,v in m['file_pins'].items() if not (ROOT/p).is_file() or sha(ROOT/p)!=v];assert not bad
 assert state['status']=='complete' and len(state['runs'])==3 and not state['owned_descendants_remaining']
 if psutil.pid_exists(state['supervisor_pid']):assert psutil.Process(state['supervisor_pid']).create_time()!=state['supervisor_create_time']
 assert all(r['owned_descendants_remaining']==[] for r in rows)
 gpu=subprocess.check_output(['nvidia-smi','--query-compute-apps=pid,process_name','--format=csv,noheader'],text=True).strip();assert not gpu
 with open('/tmp/vllm-semantic-cache-gpu.lock','a') as f:fcntl.flock(f,fcntl.LOCK_EX|fcntl.LOCK_NB);fcntl.flock(f,fcntl.LOCK_UN)
 before=shutil.disk_usage(H).free;files=[]
 for item in m['execution_order']:
  files.extend(p for p in (H/'runs'/item['name']).rglob('*') if p.is_file());files.append(H/(item['name']+'-driver-console.log.gz'))
 assert all(p.exists() for p in files);assert not any(p.suffix in ['.log','.jsonl'] for p in files)
 transitions={}
 for r in rows:
  groups=r['coverage_receipt']['wait_groups'];valid=[g for g in groups if g['first']['gpu_observation_available'] and g['last']['gpu_observation_available']]
  transitions[r['name']]={'waits':len(groups),'first_last_available':len(valid),'full_GPU_first_to_partial_last':sum(g['first']['gpu_observation_full_prefix_cached'] and not g['last']['gpu_observation_full_prefix_cached'] for g in valid),'GPU_prefix_keys_decreased':sum(g['last']['gpu_observation_cached_prefix_keys']<g['first']['gpu_observation_cached_prefix_keys'] for g in valid),'first':r['coverage_receipt']['per_wait_first'],'last':r['coverage_receipt']['per_wait_last'],'all_hints':r['coverage_receipt']['per_hint']}
 assessment={'schema':'astra-GPU-coverage-independent-assessment-v1','plan_sha256':sha(plan),'performance_eligible':False,'production_endorsement':False,'natural_eos':sum(r['natural_eos'] for r in rows),'all_observation_receipts_valid':all(r['coverage_receipt']['qualified'] for r in rows),'HTTP':{'attempts':sum(r['HTTP_receipt']['expected_total_HTTP_requests'] for r in rows),'generations':sum(r['HTTP_receipt']['generation_rows'] for r in rows),'hints':sum(r['HTTP_receipt']['hint_rows'] for r in rows),'intentional_hint_cancellations':sum(len(r['HTTP_receipt']['intentional_hint_cancellations']) for r in rows),'unexpected_exceptions':sum(len(r['HTTP_receipt']['unexpected_transport_exceptions']) for r in rows),'connection_reuse':sum(r['HTTP_receipt']['counts']['connection_reuse'] for r in rows)},'transitions':transitions,'all_zero_preemptions':all(r['first_prefill_attribution']['preemptions']==0 for r in rows),'first_admission_reconciles_all':all(r['first_prefill_attribution']['reconciles'] is True for r in rows),'store_accept_complete_balanced_all':all(r['store_balance']['balanced'] is True for r in rows),'explicit_store_failure_counter':'Unavailable, not assumed zero.','resource_and_mechanism_rows':{r['name']:{k:r[k] for k in ['load_s','tokens','resources','host_resources','thermal_clock_power','first_prefill_attribution','transfers','scheduler_counts','service_format','output_screen']} for r in rows},'judgment':'Instantaneous native GPU coverage and within-wait loss quantify a plausible retention opportunity. They do not establish that advice can prevent misses or provide positive net performance. CPU duplication may remain useful once GPU coverage is lost. This diagnostic deliberately adds queue scans and has no control arm; no timing comparison or winner claim is valid.','next_step':'A guarded native GPU free-block recency experiment is reasonable if scoped to exact ready cached keys with refcount0, identity/hash/membership validation, dense TP1 single-block layout, and invalid hint/replay/queue ownership tests. Preserve evictionability and avoid refs/pinning/reservations/copies. Separate fresh performance confirmation, correctness qualification and endurance remain required before any production endorsement.','limitations':['Inputs are spent; three candidate-only diagnostic workflows.','Per-hint/per-wait key observations repeat prefixes and shared roots; not unique bytes or capacity demand.','First/last observations stop before application return, so not exact demand-time coverage.','Missing/unavailable coverage must remain explicit; cached replay excluded.','First-admission token attribution is not cumulative physical executed prefill.','Baseline model reasoning/format defects remain; human-reviewed drafts only, productivity unmeasured.','4096-identity bound and continuous endurance still unqualified.']}
 write(H/'live-nov3-gpu-coverage-independent-assessment.json',assessment)
 inventory={'schema':'astra-GPU-coverage-handback-v1','at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'custody':'ASTRA -> ROOT','pins_checked':len(m['file_pins']),'pin_mismatches':bad,'supervisor_exited':True,'all_runner_descendants_exited':True,'owned_processes_remaining':[],'gpu_compute_processes':gpu,'gpu_lock_available':True,'free_bytes_before_cleanup':before,'free_bytes_after_cleanup':shutil.disk_usage(H).free,'removed_files':[],'retained_bytes':sum(p.stat().st_size for p in files),'retained_files':[{'path':str(p.relative_to(ROOT)),'bytes':p.stat().st_size} for p in files],'reason':'Useful raw evidence, per-run archives and compressed logs preserved. No disposable downloads/worktrees/checkpoints/uncompressed logs/owned processes remain. Previous promotion inventory remains retained; shared caches and all earlier results untouched.'};write(H/'live-nov3-gpu-coverage-handback-inventory.json',inventory)
 print(json.dumps({'HTTP':assessment['HTTP'],'transitions':transitions,'retained_bytes':inventory['retained_bytes'],'cleanup_complete':True},indent=2))
if __name__=='__main__':main()
